 if(a==='theme'||a==='set-theme'){appearance.theme=a==='theme'?(appearance.theme==='dark'?'light':'dark'):el.dataset.theme;applyAppearance();render(true);document.querySelectorAll('.theme-choice').forEach(b=>{b.classList.toggle('is-active',b.dataset.theme===appearance.theme);b.setAttribute('aria-pressed',b.dataset.theme===appearance.theme);});return;}
