function demoDigits(value){return String(value).replace(/[۰-۹]/g,c=>String(c.charCodeAt(0)-1776)).replace(/[٠-٩]/g,c=>String(c.charCodeAt(0)-1632));}
function loginScreen(){
 document.querySelector('#overlays').replaceChildren();
 document.querySelector('#app').innerHTML='<main class="ws login"><b>MORIYATI</b><h1>ورود به فضای کار</h1><form id="demo-login"><label>نام کاربری<input name="user" required autocomplete="username"></label><label>رمز عبور<input name="pass" type="password" required autocomplete="current-password"></label><button class="primary">ورود</button><p role="status"></p></form></main>';
 document.querySelector('#demo-login').onsubmit=e=>{e.preventDefault();const f=e.target.elements,id=Object.keys(roles).find(k=>roles[k].name===f.user.value.trim()||k===f.user.value.trim().toLowerCase());if(!id||demoDigits(f.pass.value)!=='1234'){e.target.querySelector('p').textContent='نام یا رمز درست نیست.';return;}sessionStorage.setItem('erp-demo-user',id);switchPersonalAccount(id);applyAppearance();const linked=location.hash.startsWith('#/')&&location.hash.length>2;const allowed=ui.route!=='task'||visibleTasks().some(t=>t.id===ui.params[0]);if(linked&&allowed){render();}else{nav(isManagementAccount()?'home':'messages');}};
}
document.addEventListener('click',e=>{if(e.target.closest('[data-logout]')){if(live){live.logout().catch(error=>toast(error.message));return;}sessionStorage.removeItem('erp-demo-user');if(window.parent!==window)window.parent.location.reload();else location.reload();}if(e.target.closest('[data-action="work-profile-detail"]')){ui.slide=Number(e.target.closest('button').dataset.index);const trigger=document.createElement('button');trigger.dataset.action='profile-records';document.body.append(trigger);trigger.click();trigger.remove();}});
document.addEventListener('change',e=>{const k=e.target.dataset.widget;if(!k||!isManagementAccount())return;const prefs=accountSpaces[appearance.role];const hidden=new Set(prefs.hiddenWidgets||[]);if(e.target.checked)hidden.delete(k);else hidden.add(k);prefs.hiddenWidgets=[...hidden];save();render(true);document.querySelector('[data-widget]')?.closest('details')?.setAttribute('open','');});
const flow=workshop({roles,saveAndConfirm,actor:()=>appearance.role,modal,closeModal,save,render,nav,toast,fileData,task:taskById,add:t=>tasks.unshift(t),factory:()=>factory,canProduct:()=>capabilities.production(appearance.role)});
const authenticated=live?live.person.userId:sessionStorage.getItem('erp-demo-user');if(authenticated&&roles[authenticated]&&appearance.role!==authenticated)switchPersonalAccount(authenticated);
applyAppearance();routeFromHash();render();

setInterval(()=>chat.tick(),30000);
